// single-item input: one Settings row drives the whole run.
const cfg = $('Settings').first().json;

// Both lists are pipe separated because a buyer question contains commas far
// more often than it contains a pipe.
const split = (v) =>
  String(v || '')
    .split('|')
    .map((s) => s.trim())
    .filter(Boolean);

const max_questions = Math.max(1, Number(cfg.max_questions) || 6);
const max_pages = Math.max(1, Number(cfg.max_pages) || 4);

const questions = split(cfg.questions);
const pages = split(cfg.trusted_pages).slice(0, max_pages);

// The form is the second way in - fired by hand the morning after you change a
// price, or when a prospect quotes something at you that you do not recognise.
// Reading it has to be guarded: on a scheduled run that node never executed,
// and reaching for that node by name throws rather than returning nothing.
let asked_now = '';
try {
  asked_now = String($('Ask One Question Now').first().json['One more question to ask'] || '').trim();
} catch (e) {
  asked_now = '';
}
if (asked_now) questions.unshift(asked_now);
questions.splice(max_questions);

// Loud on purpose. Both of these are configuration, both are empty on a fresh
// import, and a workflow that quietly asks nothing and checks nothing would
// look like it was working.
if (!questions.length) {
  throw new Error('Settings.questions is empty. Put the questions your buyers ask, separated by |');
}
if (!pages.length) {
  throw new Error('Settings.trusted_pages is empty. Put the URLs you treat as the truth, separated by |');
}

return [
  {
    json: {
      questions: questions,
      pages: pages.map((u) => ({ page_url: u })),
      payload: questions.map((q) => ({
        url: 'https://chatgpt.com/',
        prompt: q,
        country: String(cfg.country || 'US').trim(),
        web_search: true,
        additional_prompt: '',
        geolocation: '',
      })),
    },
  },
];

// Bright Data answers a validation error with HTTP 200 and an error body, so a
// green node upstream proves nothing. The refusal is carried forward rather
// than thrown, because the poll loop below has to be able to stop on it.
const raw = $('Ask ChatGPT').first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const snapshot_id = body.snapshot_id || '';

let error = '';
if (!snapshot_id) {
  error =
    String(body.error || body.message || 'no snapshot_id returned') +
    (body.errors ? ' ' + JSON.stringify(body.errors).slice(0, 200) : '');
}

return [{ json: { snapshot_id: snapshot_id, error: error } }];

const cfg = $('Settings').first().json;
const job = $('Track The Job').first().json;

// A two-prompt job with web_search on was still running at 230s when this was
// measured, so the cap is counted in minutes rather than in tries. $runIndex is
// how many times this node has run, which is the poll count.
const max_polls = Math.max(4, Number(cfg.max_polls) || 40);
const polls = $runIndex + 1;

// single-item input: one snapshot is being polled, so the progress node emits
// exactly one item and reading the first is reading all of it.
const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const status = job.snapshot_id ? String(body.status || 'running') : 'refused';

const done = status === 'ready' || status === 'failed' || status === 'refused';
const timed_out = polls >= max_polls;

return [
  {
    json: {
      snapshot_id: job.snapshot_id,
      error: job.error,
      status: status,
      ready: done || timed_out,
      timed_out: timed_out && !done,
      polls: polls,
    },
  },
];

// One row per prompt. The answer arrives four ways and they are not
// equivalent: `answer_text_markdown` keeps the bullet structure that plan names
// and prices live inside, and `answer_text` flattens the same answer into a
// paragraph - which is exactly where a price stops being attached to a plan.
// Measured live on 2026-08-26.
const state = $('Answers Ready?').first().json;
const product = String($('Settings').first().json.product_name || '').trim();

const strip = (s) =>
  String(s || '')
    // Inline citation chips are welded into the prose: the raw text contained
    // "Enterprise - Custom pricing BBright Data". Markdown images and
    // utm_source=chatgpt.com links are the two shapes they arrive in.
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]*)\]\([^)]*utm_source=chatgpt\.com[^)]*\)/g, '$1')
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const rows = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.error || r.message) {
    rows.push({
      json: { failed: true, product_name: product, reason: String(r.error || r.message).slice(0, 300) },
    });
    continue;
  }
  const text = strip(r.answer_text_markdown || r.answer_text_raw || r.answer_text);
  if (!text) continue;

  // `web_search_triggered` came back false on a run that returned citations, so
  // it is recorded and not trusted. The citations array is the honest signal.
  const cites = Array.isArray(r.citations) ? r.citations : [];
  rows.push({
    json: {
      question: String(r.prompt || ''),
      answer: text.slice(0, 6000),
      asked_at: String(r.prompt_sent_at || r.timestamp || ''),
      country: String(r.country || ''),
      product_name: product,
      sources: cites
        .filter((c) => c && c.url)
        .slice(0, 8)
        .map((c) => ({ url: String(c.url).split('?')[0], title: String(c.title || '') })),
      web_search_triggered: r.web_search_triggered === true,
      failed: false,
    },
  });
}

if (!rows.length) {
  // Never return zero items: a node emitting nothing ends its branch, and the
  // "nothing to report" path further down would then never fire either.
  rows.push({
    json: {
      failed: true,
      product_name: product,
      reason: state.timed_out
        ? 'ChatGPT did not answer within the poll cap'
        : state.error || 'no answers came back',
    },
  });
}
return rows;

