// The Information Extractor REPLACES the item rather than merging into it, so
// every row arrives as {output: {...}} and the question it belongs to has gone.
// The join back is positional, on the order the extractor received.
const cfg = $('Settings').first().json;
const asked = $('Clean The Answers').all().map((x) => x.json);
const items = $input.all();

const KINDS = {
  price: 'price', pricing: 'price', cost: 'price',
  limit: 'limit', quota: 'limit', limits: 'limit',
  feature: 'feature', features: 'feature', capability: 'feature',
  integration: 'integration', integrations: 'integration',
  plan: 'plan', plans: 'plan', tier: 'plan',
  availability: 'availability', available: 'availability', region: 'availability',
};

const per_answer = Math.max(1, Number(cfg.max_claims_per_answer) || 6);
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = asked[i];
  if (!src || src.failed) continue;
  const read = (items[i].json && items[i].json.output) || {};
  const claims = Array.isArray(read.claims) ? read.claims : [];

  for (const c of claims.slice(0, per_answer)) {
    const text = String((c && c.text) || '').trim();
    if (!text) continue;
    out.push({
      json: {
        claim: text.slice(0, 300),
        // The model ignores a schema's enum often enough to plan for, so this
        // is folded back to a known word before it reaches a Slack line.
        kind: KINDS[String((c && c.kind) || '').toLowerCase().trim()] || 'other',
        said_in_answer: String((c && c.quote) || '').slice(0, 300),
        question: src.question,
        asked_at: src.asked_at,
        sources: src.sources || [],
        product_name: src.product_name,
      },
    });
  }
}

if (!out.length) {
  out.push({ json: { claim: '', nothing_to_check: true, product_name: cfg.product_name } });
}
return out;

// The Web Unlocker returns markdown, which is already close to what a model
// reads best. What has to go is the furniture - nav, cookie banners, footers -
// because it is the same on every page and it dilutes the part that carries the
// price.
// The Web Unlocker replaces each item with the fetched body, so the URL that
// was asked for is gone by the time it lands here. The join back is positional,
// against the split that fed it - one request in, one response out, in order.
const asked = $('One Page At A Time').all().map((x) => x.json);
const items = $input.all();

const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const body = typeof r.data === 'string' ? r.data : typeof r === 'string' ? r : r.body || '';
  const url = (asked[i] && asked[i].page_url) || '';
  const text = String(body || '')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  // An empty body is not an empty page. Measured on 2026-08-26: the Web
  // Unlocker answers brightdata.com with HTTP 200 and zero bytes on every URL
  // tried, while n8n.io returns 24 KB. Treating that silence as "your page does
  // not mention it" would turn every claim into an accusation that ChatGPT
  // invented something your site actually says.
  out.push({
    json: {
      page_url: url,
      text: text.slice(0, 20000),
      length: text.length,
      fetched: text.length > 0,
    },
  });
}

if (!out.length) {
  // Same trap as an empty Sheets read: zero items ends the branch, and the
  // Merge below would then wait for something that never arrives.
  out.push({ json: { page_url: '', text: '', length: 0, fetched: false } });
}
return out;

// The Merge above is a barrier, not a data join - it exists so this node can
// safely reach back to both branches by name. One item per claim, each carrying
// the page text it will be checked against.
const cfg = $('Settings').first().json;
const claims = $('List The Claims').all().map((x) => x.json).filter((c) => c.claim);
const all_pages = $('Clean Your Pages').all().map((x) => x.json);
const pages = all_pages.filter((p) => p.text);
// Which pages came back empty, so the report can say so rather than quietly
// judging every claim against half your site.
const unreadable = all_pages.filter((p) => p.page_url && !p.fetched).map((p) => p.page_url);

const budget = Math.max(2000, Number(cfg.page_chars_per_check) || 12000);
const per_page = Math.max(500, Math.floor(budget / Math.max(1, pages.length)));

// Measured on 2026-08-26: n8n's pricing page is 19,894 characters of markdown.
// Splitting a 12,000 character budget across two pages showed the checker the
// nav and the hero and none of the plan table - and every claim about a plan
// then came back "not on the page", which is a finding the run had not earned.
let truncated = false;
const combined = pages
  .map((p) => {
    if (p.text.length > per_page) truncated = true;
    return '### ' + p.page_url + '\n' + p.text.slice(0, per_page);
  })
  .join('\n\n');

if (!claims.length || !combined) {
  return [
    {
      json: {
        nothing_to_check: true,
        pages_text: '',
        claim: '',
        unreadable: unreadable,
        claims_found: claims.length,
        pages_read: pages.length,
        truncated: false,
      },
    },
  ];
}

return claims.map((c) => ({
  json: {
    ...c,
    pages_text: combined,
    unreadable: unreadable,
    pages_read: pages.length,
    truncated: truncated,
  },
}));

