const cfg = $('Settings').first().json;
const paired = $('Pair Claims With Pages').all().map((x) => x.json);
const items = $input.all();

// What the table already knew. The upsert below cannot read the row it is about
// to overwrite, so writing $now into first_seen every run would reset the one
// number that says how long ChatGPT has been wrong about this.
const known = {};
for (const row of $('Read What We Knew').all().map((x) => x.json)) {
  if (row && row.claim_key) known[String(row.claim_key)] = row;
}

const VERDICTS = {
  supported: 'supported', support: 'supported', true: 'supported', correct: 'supported',
  contradicted: 'contradicted', contradict: 'contradicted', false: 'contradicted',
  incorrect: 'contradicted', wrong: 'contradicted',
  not_on_page: 'not_on_page', 'not on page': 'not_on_page', missing: 'not_on_page',
  unknown: 'not_on_page', unclear: 'not_on_page',
};

// The whole point of the template. A model asked to grade another model will
// produce a confident verdict for anything, so the verdict is only accepted
// when the sentence it quoted is genuinely on the page. Normalising both sides
// first, because markdown and smart quotes both survive the fetch.
function normalise(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/[*_`#>|]/g, ' ')
    .replace(/[\s ]+/g, ' ')
    .trim();
}

const min_quote = Math.max(15, Number(cfg.min_evidence_chars) || 25);
const today = String($now.toISODate());
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = paired[i];
  if (!src || !src.claim) continue;
  const read = (items[i].json && items[i].json.output) || {};

  const verdict = VERDICTS[String(read.verdict || '').toLowerCase().trim()] || 'not_on_page';
  const evidence = String(read.evidence || '').trim();

  const haystack = normalise(src.pages_text);
  const needle = normalise(evidence);
  const quoted = needle.length >= min_quote && haystack.indexOf(needle) !== -1;

  // Stable across runs so the Data Table can tell a claim that keeps coming
  // back from a new one. Lower-cased and stripped of punctuation because the
  // wording drifts between runs even when the claim does not.
  const claim_key = normalise(src.claim).replace(/[^a-z0-9 ]/g, '').slice(0, 120);

  // Every verdict that asserts something has to be quotable. A contradiction is
  // an accusation and a confirmation is a reassurance, and both are worthless
  // if the checker cannot point at the sentence - measured on 2026-08-26, where
  // "The Starter plan costs EUR 20/month when billed annually" came back
  // supported with no quote that existed anywhere on the page.
  //
  // "Not on the page" is different again: it is only a finding when the whole
  // page was read. If the text was truncated to fit the budget then all it
  // means is "not in the part I looked at", which is not worth reporting.
  let final = verdict;
  if ((verdict === 'contradicted' || verdict === 'supported') && !quoted) final = 'unverified';
  if (verdict === 'not_on_page' && src.truncated) final = 'unverified';

  out.push({
    json: {
      claim: src.claim,
      kind: src.kind,
      question: src.question,
      said_in_answer: src.said_in_answer,
      sources: src.sources || [],
      product_name: src.product_name,
      verdict: final,
      evidence: quoted ? evidence.slice(0, 400) : '',
      quote_found_on_page: quoted,
      correct_value: String(read.correct_value || '').slice(0, 200),
      note: String(read.note || '').slice(0, 300),
      // Stable across runs so the Data Table can tell a claim that keeps coming
      // back from one that is new. Lower-cased and stripped of punctuation
      // because the wording drifts between runs even when the claim does not.
      claim_key: claim_key,
      checked_on: today,
      first_seen: (known[claim_key] && known[claim_key].first_seen) || today,
    },
  });
}

if (!out.length) {
  // The branch has to survive - a node emitting zero items ends it, and the
  // "could not check" email below would never be reached. But this marker also
  // reaches the Data Table, so it is given a fixed key rather than an empty
  // one: it then updates a single row in place instead of adding a blank row
  // every quiet run, and that row is a useful record of when the last empty
  // run happened.
  out.push({
    json: {
      nothing_to_check: true,
      verdict: 'none',
      claim: 'No claims were checked on this run.',
      claim_key: '(nothing checked)',
      checked_on: today,
      first_seen: today,
    },
  });
}
return out;

// One item, so the IF below and the report after it both run once.
//
// Reads the checker by name rather than from $input: the Data Table upsert
// above replaces each item with the stored row, and a tally built from whatever
// columns happen to be mapped is a tally that breaks the day a column changes.
const rows = $('Keep Only What Is Proven').all().map((x) => x.json).filter((r) => r.claim);
const paired = $('Pair Claims With Pages').first().json || {};
const wrong = rows.filter((r) => r.verdict === 'contradicted');
const unreadable = Array.isArray(paired.unreadable) ? paired.unreadable : [];

// "Nothing was wrong" and "I could not check" have to be different answers.
// The first run of this template checked zero claims - every trusted page had
// come back empty - and the workflow reported a clean bill of health, which is
// the worst thing a checker can do.
const could_not_check = rows.length === 0 || Number(paired.pages_read || 0) === 0;

return [
  {
    json: {
      has_problems: wrong.length > 0 || rows.filter((r) => r.verdict === 'not_on_page').length > 0 || unreadable.length > 0 || could_not_check,
      could_not_check: could_not_check,
      unreadable: unreadable,
      pages_read: Number(paired.pages_read || 0),
      truncated: paired.truncated === true,
      checked: rows.length,
      wrong: wrong.length,
      unverified: rows.filter((r) => r.verdict === 'unverified').length,
      not_on_page: rows.filter((r) => r.verdict === 'not_on_page').length,
      supported: rows.filter((r) => r.verdict === 'supported').length,
    },
  },
];

// The deliverable is a table of claims next to the sentences that settle them,
// which is a document rather than a ping - so it goes out as HTML to whoever
// owns the pricing page, not as a Slack line that scrolls away.
//
// Reads the checked rows by name rather than from $input, because the Data
// Table upsert above replaces each item with the stored row - measured on
// n8n 2.36.7, where an item carrying ten fields came out holding only the five
// mapped columns plus id, createdAt and updatedAt.
const cfg = $('Settings').first().json;
const rows = $('Keep Only What Is Proven').all().map((x) => x.json).filter((r) => r.claim);
const tally = $('Decide What To Say').first().json;
const product = String(cfg.product_name || 'your product');

const F = 'system-ui,-apple-system,sans-serif';
function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const wrong = rows.filter((r) => r.verdict === 'contradicted');
const missing = rows.filter((r) => r.verdict === 'not_on_page');

const card = (r, colour) => {
  const src = (r.sources || []).slice(0, 3)
    .map((s) => '<a href="' + esc(s.url) + '" style="color:#0a58ca;text-decoration:none">' + esc(s.url.replace(/^https?:\/\//, '')) + '</a>')
    .join(', ');
  return '<div style="border-left:3px solid ' + colour + ';padding:2px 0 2px 12px;margin:0 0 18px;font:14px/1.55 ' + F + '">' +
    '<div style="color:#111"><b>ChatGPT says:</b> ' + esc(r.claim) + '</div>' +
    (r.correct_value
      ? '<div style="color:#0a7d33;margin-top:4px"><b>Your page says:</b> ' + esc(r.correct_value) + '</div>'
      : '') +
    (r.evidence
      ? '<div style="color:#555;margin-top:4px;font-style:italic">"' + esc(r.evidence) + '"</div>'
      : '') +
    '<div style="color:#888;font-size:12px;margin-top:6px">asked: ' + esc(r.question) +
    (src ? ' &nbsp;|&nbsp; it read: ' + src : '') + '</div>' +
    '</div>';
};

const blocks = [];

if (tally.could_not_check || (tally.unreadable || []).length) {
  blocks.push(
    '<div style="background:#fff4f4;border:1px solid #f0c0c0;border-radius:4px;padding:12px 14px;margin:0 0 18px;font:14px/1.55 ' + F + '">' +
      '<b style="color:#a11">' +
      (tally.could_not_check ? 'Nothing was checked this run' : 'Some of your pages could not be read') +
      '</b><div style="color:#444;margin-top:4px">' +
      ((tally.unreadable || []).length
        ? 'These came back empty: ' + esc((tally.unreadable || []).join(', ')) + '. '
        : '') +
      (tally.could_not_check
        ? 'A page that answers with an empty body is not a page that disagrees with you, so no verdicts were produced. Check the URLs, then run it again.'
        : 'Claims were only checked against the pages that did load, so a "not covered anywhere" below may just be a page that failed.') +
      '</div></div>'
  );
}

blocks.push(
  '<h2 style="font-size:20px;margin:0 0 4px">What ChatGPT is telling buyers about ' + esc(product) + '</h2>' +
  '<div style="color:#111;margin:0 0 20px">' +
  tally.checked + ' claims checked against your own pages &nbsp;|&nbsp; <b>' + tally.wrong +
  ' contradicted</b> &nbsp;|&nbsp; ' + tally.supported + ' confirmed &nbsp;|&nbsp; ' +
  tally.not_on_page + ' not covered anywhere</div>'
);

if (wrong.length) {
  blocks.push('<h3 style="font-size:15px;margin:0 0 10px;color:#a11">Wrong, and your own page proves it</h3>');
  blocks.push(wrong.slice(0, 10).map((r) => card(r, '#a11')).join(''));
}

if (missing.length) {
  blocks.push(
    '<h3 style="font-size:15px;margin:18px 0 4px;color:#9a6700">Stated about you, but nowhere on the pages you trust</h3>' +
    '<div style="color:#666;font:13px/1.5 ' + F + ';margin:0 0 10px">Either it is invented, or your own pages never say it - both are worth knowing.</div>'
  );
  blocks.push(
    '<ul style="font:14px/1.6 ' + F + ';color:#333;margin:0 0 18px;padding-left:20px">' +
    missing.slice(0, 8).map((r) => '<li>' + esc(r.claim) + ' <span style="color:#999">(' + esc(r.kind) + ')</span></li>').join('') +
    '</ul>'
  );
}

if (tally.unverified) {
  blocks.push(
    '<div style="font:13px/1.6 ' + F + ';color:#777;border-top:1px solid #eee;padding-top:10px">' +
    tally.unverified + ' claim(s) were dropped because the checker could not quote a real sentence from your pages' +
    (tally.truncated
      ? ', or because your pages were longer than the character budget and the answer may sit in the part that was cut. Raise <code>page_chars_per_check</code> in Settings'
      : '') +
    '. They are recorded in the Data Table, not reported here.</div>'
  );
}

blocks.push(
  '<p style="font:12px ' + F + ';color:#999">ChatGPT answers move between runs, so treat this as a sample. ' +
  'A claim that keeps coming back is the one worth fixing.</p>'
);

const html =
  '<div style="max-width:720px;margin:0 auto;text-align:left;font:15px/1.6 ' + F + '">' +
  blocks.join('') + '</div>';

return [{
  json: {
    html: html,
    subject: tally.could_not_check
      ? product + ' - nothing could be checked this run'
      : product + ' - ' + tally.wrong + ' thing' + (tally.wrong === 1 ? '' : 's') + ' ChatGPT gets wrong',
  },
}];
